window.kbPageData["views/entry/k-56e6fe3b4bdc8264"] = {"key":"entry/k-56e6fe3b4bdc8264","state":{"route":"entry/k-56e6fe3b4bdc8264"},"node":{"id":"k-56e6fe3b4bdc8264","mode":"k","title":"中国式现代化理论体系","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["modern"],"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"1.中国式现代化 5 个方面的中国特色：\n第一，人口规模巨大的现代化。这是中国式现代化的显著特征。\n第二，全体人民共同富裕的现代化。这是中国式现代化的本质特征，也是区别于西方现\n代化的显著标志。\n第三，物质文明和精神文明相协调的现代化。既要物质富足、也要精神富有，是中国式\n现代化的崇高追求。\n第四，…","sources":[{"id":"42a47d5d5bab1be1","label":"中国式现代化理论体系","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.中国式现代化 5 个方面的中国特色：\n第一，人口规模巨大的现代化。这是中国式现代化的显著特征。\n第二，全体人民共同富裕的现代化。这是中国式现代化的本质特征，也是区别于西方现\n代化的显著标志。\n第三，物质文明和精神文明相协调的现代化。既要物质富足、也要精神富有，是中国式\n现代化的崇高追求。\n第四，人与自然和谐共生的现代化。尊重自然、顺应自然、保护自然，促进人与自然和\n谐共生，是中国式现代化的鲜明特点。\n第五，走和平发展道路的现代化。坚持和平发展，在坚定维护世界和平与发展中谋求自\n身发展，又以自身发展更好维护世界和平与发展，推动构建人类命运共同体，是中国式现代\n化的突出特征。\n2.推进中国式现代化需要处理好若干重大关系\n一是顶层设计与实践探索的关系。二是战略与策略的关系。三是守正与创新的关系。四\n是效率与公平的关系。五是活力与秩序的关系。六是自立自强与对外开放的关系。","source":{"doc":"3ccc56f4000d1642c2d1","first":17,"last":18,"page":17,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-56e6fe3b4bdc8264":[]}};
